from collections import Counter
b=Counter()
for c in grid[0]+grid[-1]: b[c]+=1
for r in grid: b[r[0]]+=1; b[r[-1]]+=1
print("border:",b)
corners=[grid[0][0],grid[0][-1],grid[-1][0],grid[-1][-1]]
print("corners:",corners)
# horizontal adjacent same-color pairs
ph=Counter(); pv=Counter()
for r in grid:
    for a,c in zip(r,r[1:]):
        if a==c: ph[a]+=1
for j in range(30):
    for i in range(6):
        if grid[i][j]==grid[i+1][j]: pv[grid[i][j]]+=1
print("h-pairs:",ph,"v-pairs:",pv)
# largest connected components per color
import sys
sys.setrecursionlimit(10000)
H,W=len(grid),len(grid[0])
seen=[[False]*W for _ in range(H)]
comps={}
for i in range(H):
    for j in range(W):
        if not seen[i][j]:
            col=grid[i][j]; stack=[(i,j)]; seen[i][j]=True; cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and grid[ny][nx]==col:
                        seen[ny][nx]=True; stack.append((ny,nx))
            comps.setdefault(col,[]).append(cells)
for col,cs in comps.items():
    print(col,"count",sum(map(len,cs)),"ncomps",len(cs),"sizes",sorted(map(len,cs),reverse=True)[:8])
